// Tender seed data — ~300 tenders for ProcureGuard AI
// Includes deliberate anomaly patterns for detection

export type Department = 'Health' | 'Infrastructure' | 'IT' | 'Education' | 'Defence' | 'Transport' | 'Environment' | 'Social Services';
export type TenderStatus = 'published' | 'closed' | 'awarded' | 'cancelled';
export type TenderCategory = 
  | 'Medical Supplies' | 'Hospital Construction' | 'Pharmaceuticals' | 'Medical Equipment' | 'Digital Health'
  | 'Road Construction' | 'Bridge' | 'Building' | 'Civil Works' | 'Urban Development' | 'Water Supply'
  | 'Software' | 'Hardware' | 'Networking' | 'Cybersecurity' | 'Data Analytics' | 'e-Governance'
  | 'School Construction' | 'Educational Materials' | 'Training' | 'Digital Education'
  | 'Defense Equipment' | 'Security Systems' | 'Aerospace'
  | 'Vehicle Fleet' | 'Road Maintenance' | 'Public Transit' | 'Aviation'
  | 'Waste Management' | 'Air Quality' | 'Water Treatment' | 'Solar Energy' | 'Forestry'
  | 'Social Housing' | 'Welfare Services' | 'Food Supply' | 'Sanitation';

export interface Tender {
  id: string;
  title: string;
  department: Department;
  category: TenderCategory;
  publishedAt: string;
  closingDate: string;
  awardedAt: string | null;
  estimatedValue: number;       // in INR Lakhs
  awardedValue: number | null;  // in INR Lakhs
  awardedTo: string | null;     // vendor ID
  status: TenderStatus;
  location: string;
  referenceNo: string;
  description: string;
  // Anomaly flags (set by scoring engine)
  isSingleBidder?: boolean;
  isPriceDeviation?: boolean;
  isUnusualTiming?: boolean;
  isSplitContract?: boolean;
  isSharedVendorRelation?: boolean;
  isHighWinRate?: boolean;
}

// Helper to generate dates
function daysAgo(n: number): string {
  const d = new Date('2025-09-18');
  d.setDate(d.getDate() - n);
  return d.toISOString().split('T')[0];
}

function addDays(base: string, n: number): string {
  const d = new Date(base);
  d.setDate(d.getDate() + n);
  return d.toISOString().split('T')[0];
}

// Weekend award date (Saturday)
function weekendDate(daysAgo_: number): string {
  const d = new Date('2025-09-18');
  d.setDate(d.getDate() - daysAgo_);
  // Push to previous Saturday
  while (d.getDay() !== 6) d.setDate(d.getDate() - 1);
  return d.toISOString().split('T')[0];
}

